mapper.select:
SELECT ts.submission_no, ts.status, ts.created_at, ts.evidence_text, t.task_no, t.title AS task_title, t.point_reward, u.username, u.email AS user_email FROM task_submission AS ts LEFT JOIN task AS t ON ts.task_id = t.id LEFT JOIN users AS u ON ts.user_id = u.id
ts.status = #{status}
ORDER BY ts.created_at DESC
